import threading

def safe_count(threads, per_thread):
    total = [0]
    lock = threading.Lock()

    def work():
        for _ in range(per_thread):
            with lock:
                total[0] += 1

    ts = [threading.Thread(target=work) for _ in range(threads)]
    for t in ts:
        t.start()
    for t in ts:
        t.join()
    return total[0]

