lessons.solution:
import threading

def threaded_squares(nums):
    squares = [0] * len(nums)
    total = [0]
    lock = threading.Lock()

    def work(i, n):
        squares[i] = n * n
        with lock:
            total[0] += n * n

    ts = [threading.Thread(target=work, args=(i, n)) for i, n in enumerate(nums)]
    for t in ts:
        t.start()
    for t in ts:
        t.join()
    return (squares, total[0])

