class Clamp:
    def __set_name__(self, owner, name):
        self.name = '_' + name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, self.name, 0)

    def __set__(self, obj, value):
        setattr(obj, self.name, max(0, value))

class Product:
    price = Clamp()

    def __init__(self, price):
        self.price = price

